```typescript
import * as readline from 'readline';

function _nfloat(string: string | null): number | string {
    let result: number | string = 0;
    if (string) {
        const num = parseFloat(string);
        if (!isNaN(num)) {
            result = num;
        } else {
            const patterns: Array<{ regex: RegExp; sign: number }> = [
                { regex: /"分红\D*(\d*(?:\.\d*)?)\D*"/, sign: 1 },
                { regex: /.*现金(\d*(?:\.\d*)?)\D*/, sign: 1 },
                { regex: /.*折算(\d*(?:\.\d*)?)\D*/, sign: -1 },
                { regex: /"拆分\D*(\d*(?:\.\d*)?)\D*"/, sign: -1 },
                { regex: /\D*分拆(\d*(?:\.\d*)?)\D*/, sign: -1 }
            ];
            let matched = false;
            for (const p of patterns) {
                const m = string.match(p.regex);
                if (m) {
                    result = p.sign * parseFloat(m[1]);
                    matched = true;
                    break;
                }
            }
            if (!matched) {
                // ログ出力は省略（標準出力に余計なものを出さないため）
                result = string;
            }
        }
    }
    return result;
}

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const input = line === '' ? null : line;
    const output = _nfloat(input);
    if (typeof output === 'number') {
        console.log(output.toString());
    } else {
        console.log(output);
    }
    rl.close();
});
