実装方針: 標準入力から引数(ファイルパス)を読み、JSONをパースして該当カテゴリのイベントを集計し、辞書をJSON文字列として出力します。

```typescript
import * as fs from 'fs';

function indexHostEntities(path: string): Record<string, { calls: number; total_us: number; cat_counts: Record<string, number> }> {
    const idx: Record<string, { calls: number; total_us: number; cat_counts: Record<string, number> }> = {};
    let data: any;
    try {
        const raw = fs.readFileSync(path, 'utf-8');
        data = JSON.parse(raw);
    } catch {
        return idx;
    }
    const events = Array.isArray(data) ? data : (data?.traceEvents ?? []);
    const host = new Set(['cpu_op', 'user_annotation', 'cuda_runtime', 'hip_runtime']);
    for (const e of events) {
        if (typeof e !== 'object' || e === null) continue;
        const cat = e.cat;
        if (!host.has(cat)) continue;
        const name = e.name ?? '?';
        if (!idx[name]) {
            idx[name] = { calls: 0, total_us: 0.0, cat_counts: {} };
        }
        idx[name].calls += 1;
        idx[name].total_us += Number(e.dur ?? 0) || 0;
        idx[name].cat_counts[cat] = (idx[name].cat_counts[cat] ?? 0) + 1;
    }
    return idx;
}

function main() {
    const lines: string[] = [];
    const reader = require('readline').createInterface({ input: process.stdin });
    reader.on('line', (line: string) => lines.push(line));
    reader.on('close', () => {
        const path = lines[0] ?? '';
        const result = indexHostEntities(path);
        console.log(JSON.stringify(result));
    });
}

main();
```

実装方針: 入力された要素が文字列ならテキストパートに変換し、`to_content_part`メソッドがあればそれを呼び出し、それ以外はそのまま返す。

```typescript
import * as readline from 'readline';

function normalizeContentElement(element: any): any {
    if (typeof element === 'string') {
        return { type: 'text', text: element };
    }
    if (element !== null && typeof element === 'object' && typeof element.to_content_part === 'function') {
        return element.to_content_part();
    }
    return element;
}

// 入力読み取り
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    terminal: false
});

let inputLines: string[] = [];
rl.on('line', (line) => {
    inputLines.push(line);
});

rl.on('close', () => {
    // 入力は1行のみ（要素の値）
    const input = inputLines[0];
    let result: any;
    if (input === '') {
        result = normalizeContentElement(null);
    } else {
        // 文字列かどうか判定（引用符なしの文字列）
        // ここでは単純に文字列として扱う（入力形式に従い、文字列はそのまま）
        result = normalizeContentElement(input);
    }
    // 出力をPythonのrepr形式に変換
    const output = formatValue(result);
    console.log(output);
});

function formatValue(value: any): string {
    if (value === null) return '';
    if (typeof value === 'boolean') return value ? 'True' : 'False';
    if (typeof value === 'number') return String(value);
    if (typeof value === 'string') return value;
    if (Array.isArray(value)) {
        return '[' + value.map(formatValue).join(', ') + ']';
    }
    if (typeof value === 'object') {
        const entries = Object.entries(value).map(([k, v]) => {
            const key = /^[A-Za-z_][A-Za-z0-9_]*$/.test(k) ? k : `'${k}'`;
            return `${key}: ${formatValue(v)}`;
        });
        return '{' + entries.join(', ') + '}';
    }
    return String(value);
}
```

実装方針: 標準入力から4つの引数（tp_size, pp_size, dp_size, virtual_pp_size）を読み取り、Python関数と同じロジックでグループを計算し、指定された出力形式でリストを出力します。

```typescript
import * as readline from 'readline';

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let lines: string[] = [];
rl.on('line', (line) => {
    lines.push(line);
});

rl.on('close', () => {
    const tp_size = lines[0] !== '' ? parseInt(lines[0]) : 1;
    const pp_size = lines[1] !== '' ? parseInt(lines[1]) : 1;
    const dp_size = lines[2] !== '' ? parseInt(lines[2]) : 1;
    // virtual_pp_sizeは未使用だが読み取る
    // lines[3]はvirtual_pp_size

    const world_size = tp_size * pp_size * dp_size;
    const tensor_model_parallel_size = Math.min(tp_size, world_size);
    const pipeline_model_parallel_size = Math.min(pp_size, world_size);
    const data_parallel_size = world_size / (tensor_model_parallel_size * pipeline_model_parallel_size);
    const num_tensor_model_parallel_groups = world_size / tensor_model_parallel_size;
    const num_pipeline_model_parallel_groups = world_size / pipeline_model_parallel_size;
    const num_data_parallel_groups = world_size / data_parallel_size;

    const all_dp_group_ranks: number[][] = [];
    for (let i = 0; i < pipeline_model_parallel_size; i++) {
        const start_rank = i * num_pipeline_model_parallel_groups;
        const end_rank = (i + 1) * num_pipeline_model_parallel_groups;
        for (let j = 0; j < tensor_model_parallel_size; j++) {
            const ranks: number[] = [];
            for (let r = start_rank + j; r < end_rank; r += tensor_model_parallel_size) {
                ranks.push(r);
            }
            all_dp_group_ranks.push(ranks);
        }
    }

    const all_pp_group_ranks: number[][] = [];
    for (let i = 0; i < data_parallel_size; i++) {
        const ranks: number[] = [];
        for (const dp_group of all_dp_group_ranks) {
            ranks.push(dp_group[i]);
        }
        all_pp_group_ranks.push(ranks);
    }

    const all_tp_group_ranks: number[][] = [];
    for (let i = 0; i < num_tensor_model_parallel_groups; i++) {
        const ranks: number[] = [];
        for (let r = i * tensor_model_parallel_size; r < (i + 1) * tensor_model_parallel_size; r++) {
            ranks.push(r);
        }
        all_tp_group_ranks.push(ranks);
    }

    // 出力形式: リストのリストなので、1行目に要素数、2行目に要素を空白区切り
    // ここでは3つのリストを出力する
    const result = [all_tp_group_ranks, all_pp_group_ranks, all_dp_group_ranks];
    // 出力形式: リストは1行目に要素数、2行目に要素を空白区切り
    // 要素がリストの場合はPythonのrepr表記
    console.log(result.length);
    console.log(result.map((list) => JSON.stringify(list).replace(/,/g, ', ')).join(' '));
});
```

