    }

    // 簡易的なパーサー - 実際の入力形式に合わせて拡張が必要
    private static Object parseValue(String s) {
        if (s.isEmpty()) return null;
        if (s.equals("true")) return true;
        if (s.equals("false")) return false;
        try {
            if (s.contains(".") || s.contains("e") || s.contains("E")) {
                return Double.parseDouble(s);
            } else {
                return Integer.parseInt(s);
            }
        } catch (NumberFormatException e) {
            return s;
        }
    }

    // 出力フォーマット
    private static String formatOutput(Object obj) {
        if (obj instanceof int[] || obj instanceof double[] || obj instanceof Object[]) {
            Object[] arr = (Object[]) obj;
            return arr[0] + " " + arr[1];
        }
        return obj.toString();
    }

    // 元の関数の移植
    public static Object _asPair(Object value, Object singleY) {
        if (value instanceof Integer || value instanceof Double || value instanceof Float) {
            Number num = (Number) value;
            if (singleY == null) {
                return new Object[]{num, num};
            } else {
                return new Object[]{num, singleY};
            }
        }
        if (value instanceof List) {
            List<?> list = (List<?>) value;
            if (list.size() == 2) {
                return new Object[]{list.get(0), list.get(1)};
            }
        }
        throw new IllegalArgumentException(value.toString());
    }
}
