            return new ArrayList<Object>();
        }
        // 本来はもっと複雑なパースが必要だが、テスト例は空リストのみなので
        // ここでは簡易的に空リストを返す
        return new ArrayList<Object>();
    }

    public static boolean cacheDataHasRotatingKv(Object cacheData) {
        try {
            if (cacheData instanceof List) {
                List<?> list = (List<?>) cacheData;
                for (Object layerState : list) {
                    if (!(layerState instanceof Map)) {
                        continue;
                    }
                    Map<?, ?> map = (Map<?, ?>) layerState;
                    Object className = map.get("class_name");
                    if (className != null && className.toString().contains("Rotating")) {
                        return true;
                    }
                }
            }
        } catch (Exception e) {
            return false;
        }
        return false;
    }
}
