実装方針: Pythonの丸め処理(銀行丸めではなく通常の四捨五入)を再現するため、`std::round`を使用し、重複を排除して出力します。

```cpp
#include <iostream>
#include <vector>
#include <set>
#include <cmath>
#include <algorithm>

std::vector<int> spread_indices(int total, int k) {
    std::vector<int> result;
    if (k <= 0 || total <= 0) return result;
    if (k >= total) {
        for (int i = 0; i < total; ++i) result.push_back(i);
        return result;
    }
    if (k == 1) {
        result.push_back(0);
        return result;
    }
    std::vector<int> indices;
    for (int i = 0; i < k; ++i) {
        double val = static_cast<double>(i) * (total - 1) / (k - 1);
        indices.push_back(static_cast<int>(std::round(val)));
    }
    std::set<int> seen;
    for (int idx : indices) {
        if (seen.find(idx) == seen.end()) {
            seen.insert(idx);
            result.push_back(idx);
        }
    }
    return result;
}

int main() {
    int total, k;
    std::cin >> total >> k;
    std::vector<int> out = spread_indices(total, k);
    std::cout << out.size() << "\n";
    for (size_t i = 0; i < out.size(); ++i) {
        if (i > 0) std::cout << " ";
        std::cout << out[i];
    }
    std::cout << "\n";
    return 0;
}
