説明文: 標準入力から1行読み取り、Pythonの関数と同じ検証ロジックをC++で実装し、結果をタプル形式で出力します。

```cpp
#include <iostream>
#include <string>
#include <tuple>
#include <vector>
#include <algorithm>
#include <cctype>

std::tuple<bool, std::string> validate_name(const std::string& input) {
    std::string name = input;
    // 空チェック
    if (name.empty()) {
        return {false, "Name cannot be empty"};
    }
    // 前後の空白を除去してチェック
    std::string trimmed = name;
    // 先頭の空白除去
    size_t start = trimmed.find_first_not_of(" \t\n\r\f\v");
    if (start == std::string::npos) {
        return {false, "Name cannot be empty"};
    }
    trimmed = trimmed.substr(start);
    // 末尾の空白除去
    size_t end = trimmed.find_last_not_of(" \t\n\r\f\v");
    if (end != std::string::npos) {
        trimmed = trimmed.substr(0, end + 1);
    }
    if (trimmed.empty()) {
        return {false, "Name cannot be empty"};
    }
    // 長さチェック
    if (trimmed.length() > 50) {
        return {false, "Name too long (max 50 characters)"};
    }
    // 禁止文字チェック
    std::string forbidden = ":{},&*#?|-<>=!%@`\"'";
    for (char c : trimmed) {
        if (forbidden.find(c) != std::string::npos) {
            return {false, "Name contains forbidden character: " + std::string(1, c)};
        }
    }
    // 前後の空白チェック（元のnameとtrimmedを比較）
    if (name != trimmed) {
        return {false, "Name has leading/trailing spaces"};
    }
    // 制御文字チェック
    for (char c : name) {
        if (static_cast<unsigned char>(c) < 32) {
            return {false, "Name contains control characters"};
        }
    }
    return {true, ""};
}

int main() {
    std::string input;
    std::getline(std::cin, input);
    auto result = validate_name(input);
    // 出力形式: タプル (bool, string)
    std::cout << "2\n";
