実装方針: 入力されたJSON文字列をパースし、イベントを処理して、指定されたロジックに従ってエッジ情報を構築し、結果をJSON形式で出力します。

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <sstream>
#include <cctype>
#include <cmath>

// 簡易JSONパーサー（必要な部分のみ）
class JsonValue {
public:
    enum Type { Null, Bool, Number, String, Array, Object };
    Type type;
    bool bool_val;
    double num_val;
    std::string str_val;
    std::vector<JsonValue> array;
    std::vector<std::pair<std::string, JsonValue>> object;

    JsonValue() : type(Null), bool_val(false), num_val(0) {}
};

class JsonParser {
    std::string input;
    size_t pos;
public:
    JsonParser(const std::string& s) : input(s), pos(0) {}

    JsonValue parse() {
        skip_ws();
        return parse_value();
    }

private:
    void skip_ws() {
        while (pos < input.size() && isspace(input[pos])) pos++;
    }

    JsonValue parse_value() {
        if (pos >= input.size()) return JsonValue();
        char c = input[pos];
        if (c == '{') return parse_object();
        if (c == '[') return parse_array();
        if (c == '"') return parse_string();
        if (c == 't' || c == 'f') return parse_bool();
        if (c == 'n') { pos += 4; return JsonValue(); } // null
        return parse_number();
    }

    JsonValue parse_object() {
        JsonValue obj;
        obj.type = JsonValue::Object;
        pos++; // skip {
        skip_ws();
        if (pos < input.size() && input[pos] == '}') { pos++; return obj; }
        while (pos < input.size()) {
            skip_ws();
            std::string key = parse_string().str_val;
            skip_ws();
            if (pos < input.size() && input[pos] == ':') pos++;
            skip_ws();
            JsonValue val = parse_value();
            obj.object.push_back({key, val});
            skip_ws();
            if (pos < input.size() && input[pos] == ',') { pos++; continue; }
            if (pos < input.size() && input[pos] == '}') { pos++; break; }
        }
        return obj;
    }

    JsonValue parse_array() {
        JsonValue arr;
        arr.type = JsonValue::Array;
        pos++; // skip [
        skip_ws();
        if (pos < input.size() && input[pos] == ']') { pos++; return arr; }
        while (pos < input.size()) {
            skip_ws();
            JsonValue val = parse_value();
            arr.array.push_back(val);
            skip_ws();
            if (pos < input.size() && input[pos] == ',') { pos++; continue; }
            if (pos < input.size() && input[pos] == ']') { pos++; break; }
        }
        return arr;
    }

    JsonValue parse_string() {
        JsonValue str;
        str.type = JsonValue::String;
        pos++; // skip "
        std::string result;
        while (pos < input.size() && input[pos] != '"') {
            if (input[pos] == '\\' && pos+1 < input.size()) {
                pos++;
                switch (input[pos]) {
                    case 'n': result += '\n'; break;
                    case 't': result += '\t'; break;
                    case 'r': result += '\r'; break;
                    case '\\': result += '\\'; break;
                    case '"': result += '"'; break;
                    default: result += input[pos];
                }
            } else {
                result += input[pos];
            }
            pos++;
        }
        if (pos < input.size()) pos++; // skip closing "
        str.str_val = result;
        return str;
    }

    JsonValue parse_bool() {
        JsonValue b;
        b.type = JsonValue::Bool;
        if (input.compare(pos, 4, "true") == 0) {
            b.bool_val = true;
            pos += 4;
        } else {
            b.bool_val = false;
            pos += 5;
        }
        return b;
    }

    JsonValue parse_number() {
        JsonValue num;
        num.type = JsonValue::Number;
        size_t start = pos;
        while (pos < input.size() && (isdigit(input[pos]) || input[pos] == '-' || input[pos] == '+' || input[pos] == '.' || input[pos] == 'e' || input[pos] == 'E')) pos++;
        num.num_val = std::stod(input.substr(start, pos-start));
        return num;
    }
};

// JSON出力用ヘルパー
std::string json_escape(const std::string& s) {
    std::string out;
    for (char c : s) {
        if (c == '"') out += "\\\"";
        else if (c == '\\') out += "\\\\";
        else if (c == '\n') out += "\\n";
        else if (c == '\t') out += "\\t";
        else if (c == '\r') out += "\\r";
        else out += c;
    }
    return out;
}

std::string json_number(double d) {
    std::ostringstream oss;
    oss.precision(15);
    oss << d;
    std::string s = oss.str();
    // 整数なら小数点を付ける
    if (s.find('.') == std::string::npos && s.find('e') == std::string::npos && s.find('E') == std::string::npos) {
        s += ".0";
    }
    return s;
}

std::string json_string(const std::string& s) {
    return "\"" + json_escape(s) + "\"";
}

// メイン処理
int main() {
    // 入力をすべて読み取る
    std::string input;
    std::string line;
    while (std::getline(std::cin, line)) {
        input += line;
        input += '\n';
    }
    // 空行を除去
    while (!input.empty() && (input.back() == '\n' || input.back() == ' ')) input.pop_back();

    // 入力が空の場合は空の辞書を出力
    if (input.empty()) {
        std::cout << "{}" << std::endl;
        return 0;
    }

    // JSONパース
    JsonParser parser(input);
    JsonValue data = parser.parse();

    // traceEvents を取得
    std::vector<JsonValue> events;
    if (data.type == JsonValue::Array) {
        events = data.array;
    } else if (data.type == JsonValue::Object) {
        for (auto& kv : data.object) {
            if (kv.first == "traceEvents" && kv.second.type == JsonValue::Array) {
                events = kv.second.array;
                break;
            }
        }
    }

    // host_by_ext: ext -> set of host names
    std::map<std::string, std::set<std::string>> host_by_ext;
    // spans_by_thread: (pid, tid) -> vector of (start, end, name, ext)
    std::map<std::pair<long long, long long>, std::vector<std::tuple<double, double, std::string, std::string>>> spans_by_thread;

    for (const auto& event : events) {
        if (event.type != JsonValue::Object) continue;
        std::string cat;
        for (auto& kv : event.object) {
            if (kv.first == "cat" && kv.second.type == JsonValue::String) {
                cat = kv.second.str_val;
                break;
            }
        }
        if (cat != "cpu_op" && cat != "user_annotation") continue;

        // External id
        std::string ext;
        bool has_ext = false;
        for (auto& kv : event.object) {
            if (kv.first == "args" && kv.second.type == JsonValue::Object) {
                for (auto& arg : kv.second.object) {
                    if (arg.first == "External id") {
                        if (arg.second.type == JsonValue::Number) {
                            ext = json_number(arg.second.num_val);
                            has_ext = true;
                        } else if (arg.second.type == JsonValue::String) {
                            ext = arg.second.str_val;
                            has_ext = true;
                        }
                        break;
                    }
                }
                break;
            }
        }

        std::string name = "?";
        for (auto& kv : event.object) {
            if (kv.first == "name" && kv.second.type == JsonValue::String) {
                name = kv.second.str_val;
                break;
            }
        }

        if (has_ext) {
            host_by_ext[ext].insert(name);
        }

        // ts and dur
        double ts = 0;
        bool has_ts = false;
        double dur = 0;
        for (auto& kv : event.object) {
            if (kv.first == "ts" && kv.second.type == JsonValue::Number) {
                ts = kv.second.num_val;
                has_ts = true;
            }
            if (kv.first == "dur" && kv.second.type == JsonValue::Number) {
                dur = kv.second.num_val;
            }
        }

        if (has_ext && has_ts) {
            long long pid = 0, tid = 0;
            for (auto& kv : event.object) {
                if (kv.first == "pid" && kv.second.type == JsonValue::Number) pid = (long long)kv.second.num_val;
                if (kv.first == "tid" && kv.second.type == JsonValue::Number) tid = (long long)kv.second.num_val;
            }
            spans_by_thread[{pid, tid}].push_back({ts, ts + dur, name, ext});
        }
    }

    // スパン処理
    for (auto& kv : spans_by_thread) {
        auto& spans = kv.second;
        std::sort(spans.begin(), spans.end(), [](const auto& a, const auto& b) {
            if (std::get<0>(a) != std::get<0>(b)) return std::get<0>(a) < std::get<0>(b);
            return std::get<1>(a) > std::get<1>(b);
        });
        std::vector<std::pair<double, std::string>> stack;
        for (const auto& span : spans) {
            double start = std::get<0>(span);
            double end = std::get<1>(span);
            const std::string& name = std::get<2>(span);
            const std::string& ext = std::get<3>(span);
            while (!stack.empty() && stack.back().first <= start) {
                stack.pop_back();
            }
            auto& names = host_by_ext[ext];
            names.insert(name);
            for (const auto& parent : stack) {
                names.insert(parent.second);
            }
            stack.push_back({end, name});
        }
    }

    // エッジ構築
    std::map<std::string, std::map<std::string, std::pair<int, double>>> edges;
    for (const auto& event : events) {
        if (event.type != JsonValue::Object) continue;
        std::string cat;
        for (auto& kv : event.object) {
            if (kv.first == "cat" && kv.second.type == JsonValue::String) {
                cat = kv.second.str_val;
                break;
            }
        }
        if (cat != "kernel") continue;

        std::string ext;
        bool has_ext = false;
        for (auto& kv : event.object) {
            if (kv.first == "args" && kv.second.type == JsonValue::Object) {
                for (auto& arg : kv.second.object) {
                    if (arg.first == "External id") {
                        if (arg.second.type == JsonValue::Number) {
                            ext = json_number(arg.second.num_val);
                            has_ext = true;
                        } else if (arg.second.type == JsonValue::String) {
                            ext = arg.second.str_val;
                            has_ext = true;
                        }
                        break;
                    }
                }
                break;
            }
        }

        std::string name = "?";
        for (auto& kv : event.object) {
            if (kv.first == "name" && kv.second.type == JsonValue::String) {
                name = kv.second.str_val;
                break;
            }
        }

        double dur = 0;
        for (auto& kv : event.object) {
            if (kv.first == "dur" && kv.second.type == JsonValue::Number) {
                dur = kv.second.num_val;
            }
        }

        if (has_ext) {
            auto it = host_by_ext.find(ext);
            if (it != host_by_ext.end()) {
                for (const auto& host : it->second) {
                    auto& child = edges[host][name];
                    child.first++;
                    child.second += dur;
                }
            }
        }
    }

    // 出力
    std::cout << "{";
    bool first_host = true;
    for (const auto& host_pair : edges) {
        if (!first_host) std::cout << ", ";
        first_host = false;
        std::cout << json_string(host_pair.first) << ": {";
        bool first_kernel = true;
        for (const auto& kernel_pair : host_pair.second) {
            if (!first_kernel) std::cout << ", ";
