            std::cout << json_string(kernel_pair.first) << ": {\"calls\": " << kernel_pair.second.first << ", \"total_us\": " << json_number(kernel_pair.second.second) << "}";
        }
        std::cout << "}";
    }
    std::cout << "}" << std::endl;

    return 0;
}
