```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;

class Program
{
    static void Main()
    {
        string policyLine = Console.ReadLine();
        string routeArn = Console.ReadLine();

        // 辞書をパース（簡易的なPython辞書パーサー）
        var policy = ParseDict(policyLine);
        string result = EvaluateAuthorizerPolicy(policy, routeArn);
        Console.WriteLine(result);
    }

    static string EvaluateAuthorizerPolicy(Dictionary<string, object> policyDoc, string routeArn)
    {
        if (policyDoc == null) return "NoMatch";

        object stmtObj;
        if (!policyDoc.TryGetValue("Statement", out stmtObj) || stmtObj == null)
            return "NoMatch";

        List<object> statements = new List<object>();
        if (stmtObj is Dictionary<string, object>)
            statements.Add(stmtObj);
        else if (stmtObj is List<object>)
            statements = (List<object>)stmtObj;

        bool allow = false;
        foreach (var st in statements)
        {
            if (!(st is Dictionary<string, object>)) continue;
            var stDict = (Dictionary<string, object>)st;

            object resObj;
            if (!stDict.TryGetValue("Resource", out resObj) || resObj == null)
                continue;

            List<string> resources = new List<string>();
            if (resObj is string)
                resources.Add((string)resObj);
            else if (resObj is List<object>)
                resources = ((List<object>)resObj).Select(x => x.ToString()).ToList();

            if (!resources.Any(r => AuthorizerArnMatches(r, routeArn)))
                continue;

            object effectObj;
            if (stDict.TryGetValue("Effect", out effectObj) && effectObj?.ToString() == "Deny")
                return "Deny";
            if (effectObj?.ToString() == "Allow")
                allow = true;
        }
        return allow ? "Allow" : "NoMatch";
    }

    static bool AuthorizerArnMatches(string pattern, string arn)
    {
        // 簡易的なワイルドカードマッチング（* と ?）
        string regex = "^" + Regex.Escape(pattern)
            .Replace("\\*", ".*")
            .Replace("\\?", ".") + "$";
        return Regex.IsMatch(arn, regex);
    }

    // 簡易Python辞書パーサー（文字列・数値・真偽値・None・リスト・辞書をサポート）
    static Dictionary<string, object> ParseDict(string input)
    {
        int pos = 0;
        var result = ParseValue(input, ref pos) as Dictionary<string, object>;
        return result;
    }

    static object ParseValue(string s, ref int pos)
    {
        SkipWhitespace(s, ref pos);
        if (pos >= s.Length) return null;

        char c = s[pos];
        if (c == '{') return ParseDictInternal(s, ref pos);
        if (c == '[') return ParseList(s, ref pos);
        if (c == '\'') return ParseString(s, ref pos, '\'');
        if (c == '"') return ParseString(s, ref pos, '"');
        if (c == 't' && s.Substring(pos, 4) == "true") { pos += 4; return true; }
        if (c == 'f' && s.Substring(pos, 5) == "false") { pos += 5; return false; }
        if (c == 'N' && s.Substring(pos, 4) == "None") { pos += 4; return null; }
        // 数値
        int start = pos;
        while (pos < s.Length && (char.IsDigit(s[pos]) || s[pos] == '.' || s[pos] == '-' || s[pos] == '+' || s[pos] == 'e' || s[pos] == 'E'))
            pos++;
        string numStr = s.Substring(start, pos - start);
        if (numStr.Contains(".") || numStr.Contains("e") || numStr.Contains("E"))
            return double.Parse(numStr, System.Globalization.CultureInfo.InvariantCulture);
        return int.Parse(numStr);
    }

    static Dictionary<string, object> ParseDictInternal(string s, ref int pos)
    {
        var dict = new Dictionary<string, object>();
        pos++; // {
        SkipWhitespace(s, ref pos);
        if (pos < s.Length && s[pos] == '}') { pos++; return dict; }

        while (true)
        {
            SkipWhitespace(s, ref pos);
            string key = ParseString(s, ref pos, '\'');
            SkipWhitespace(s, ref pos);
            if (s[pos] == ':') pos++;
            SkipWhitespace(s, ref pos);
            object val = ParseValue(s, ref pos);
            dict[key] = val;
            SkipWhitespace(s, ref pos);
            if (pos < s.Length && s[pos] == ',') { pos++; continue; }
            if (pos < s.Length && s[pos] == '}') { pos++; break; }
        }
        return dict;
    }

    static List<object> ParseList(string s, ref int pos)
    {
        var list = new List<object>();
        pos++; // [
        SkipWhitespace(s, ref pos);
        if (pos < s.Length && s[pos] == ']') { pos++; return list; }

        while (true)
        {
            SkipWhitespace(s, ref pos);
            object val = ParseValue(s, ref pos);
            list.Add(val);
            SkipWhitespace(s, ref pos);
            if (pos < s.Length && s[pos] == ',') { pos++; continue; }
            if (pos < s.Length && s[pos] == ']') { pos++; break; }
        }
        return list;
    }

    static string ParseString(string s, ref int pos, char quote)
    {
        pos++; // skip quote
        int start = pos;
        while (pos < s.Length && s[pos] != quote)
        {
            if (s[pos] == '\\') pos++;
            pos++;
        }
        string result = s.Substring(start, pos - start);
        pos++; // skip closing quote
        return result;
    }

    static void SkipWhitespace(string s, ref int pos)
    {
        while (pos < s.Length && char.IsWhiteSpace(s[pos])) pos++;
    }
}
