```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

class Program
{
    static void Main()
    {
        // 入力読み込み
        var bamFiles = ReadStringListOrNull();
        var bigwigFiles = ReadStringListOrNull();
        var bedFiles = ReadStringListOrNull();

        var result = ValidateFiles(bamFiles, bigwigFiles, bedFiles);

        // 出力: 成功フラグとメッセージリスト
        Console.WriteLine(result.success ? "True" : "False");
        Console.WriteLine(result.messages.Count);
        if (result.messages.Count > 0)
            Console.WriteLine(string.Join(" ", result.messages.Select(m => QuoteIfNeeded(m))));
    }

    static List<string> ReadStringListOrNull()
    {
        string line = Console.ReadLine();
        if (string.IsNullOrEmpty(line))
            return null;
        int count = int.Parse(line);
        if (count == 0)
            return new List<string>();
        string elements = Console.ReadLine();
        return elements.Split(' ').ToList();
    }

    static string QuoteIfNeeded(string s)
    {
        // スペースや特殊文字を含む場合は引用符で囲む
        if (s.Contains(" ") || s.Contains("\n") || s.Contains("\t") || s.Contains("'") || s.Contains("\""))
            return "'" + s.Replace("'", "\\'") + "'";
        return s;
    }

    static (bool success, List<string> messages) ValidateFiles(
        List<string> bam_files = null,
        List<string> bigwig_files = null,
        List<string> bed_files = null)
    {
        bool allSuccess = true;
        var messages = new List<string>();

        if (bam_files != null)
        {
            messages.Add("\n=== Validating BAM Files ===");
            foreach (var bamFile in bam_files)
            {
                var (success, msg) = CheckFileExists(bamFile);
                messages.Add(msg);
                if (!success)
                {
                    allSuccess = false;
                    continue;
                }
                (success, msg) = CheckBamIndex(bamFile);
                messages.Add(msg);
                if (!success)
                    allSuccess = false;
            }
        }

        if (bigwig_files != null)
        {
            messages.Add("\n=== Validating bigWig Files ===");
            foreach (var bwFile in bigwig_files)
            {
                var (success, msg) = CheckFileExists(bwFile);
                messages.Add(msg);
                if (!success)
                {
                    allSuccess = false;
                    continue;
                }
                (success, msg) = CheckBigwigFile(bwFile);
                messages.Add(msg);
                if (!success)
                    allSuccess = false;
            }
        }

        if (bed_files != null)
        {
            messages.Add("\n=== Validating BED Files ===");
            foreach (var bedFile in bed_files)
            {
                var (success, msg) = CheckFileExists(bedFile);
                messages.Add(msg);
                if (!success)
                {
                    allSuccess = false;
                    continue;
                }
                (success, msg) = CheckBedFile(bedFile);
                messages.Add(msg);
                if (!success)
                    allSuccess = false;
            }
        }

        return (allSuccess, messages);
    }

    static (bool, string) CheckFileExists(string path)
    {
        if (File.Exists(path))
            return (true, $"File exists: {path}");
        else
            return (false, $"File not found: {path}");
    }

    static (bool, string) CheckBamIndex(string bamPath)
    {
        string indexPath = bamPath + ".bai";
        if (File.Exists(indexPath))
            return (true, $"BAM index exists: {indexPath}");
        else
            return (false, $"BAM index not found: {indexPath}");
    }

    static (bool, string) CheckBigwigFile(string path)
    {
        // 簡易チェック: 拡張子が .bw または .bigwig
        if (path.EndsWith(".bw") || path.EndsWith(".bigwig"))
            return (true, $"bigWig file valid extension: {path}");
        else
            return (false, $"Invalid bigWig extension: {path}");
    }

    static (bool, string) CheckBedFile(string path)
    {
        // 簡易チェック: 拡張子が .bed
        if (path.EndsWith(".bed"))
            return (true, $"BED file valid extension: {path}");
        else
            return (false, $"Invalid BED extension: {path}");
    }
