package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

func stableIDKey(nodeID string) string {
	// 入力は文字列として受け取るが、辞書形式かどうかを判定する
	trimmed := strings.TrimSpace(nodeID)
	if strings.HasPrefix(trimmed, "{") && strings.HasSuffix(trimmed, "}") {
		// 辞書形式の場合、JSONとしてパースしてソートキーで再シリアライズ
		var m map[string]interface{}
		if err := json.Unmarshal([]byte(trimmed), &m); err == nil {
			// キーをソート
			keys := make([]string, 0, len(m))
			for k := range m {
				keys = append(keys, k)
			}
			sort.Strings(keys)
			var sb strings.Builder
			sb.WriteString("{")
			for i, k := range keys {
				if i > 0 {
					sb.WriteString(", ")
				}
				sb.WriteString(strconv.Quote(k))
				sb.WriteString(": ")
				val := m[k]
				// 値をJSON形式で出力
				b, _ := json.Marshal(val)
				sb.Write(b)
			}
			sb.WriteString("}")
			return sb.String()
		}
	}
	return nodeID
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	input := scanner.Text()
	result := stableIDKey(input)
	fmt.Println(result)
}
